CREATE TABLE IF NOT EXISTS staff_members (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,employee_code VARCHAR(40) NOT NULL UNIQUE,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(50) NULL,department VARCHAR(120) NULL,job_title VARCHAR(150) NULL,employment_status ENUM('active','inactive','on_leave') NOT NULL DEFAULT 'active',hourly_rate DECIMAL(15,2) NOT NULL DEFAULT 0,currency VARCHAR(10) NOT NULL DEFAULT 'USD',availability_hours DECIMAL(6,2) NOT NULL DEFAULT 40,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_staff_status(employment_status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS project_resources (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,staff_id BIGINT UNSIGNED NOT NULL,role_name VARCHAR(150) NULL,allocation_percent DECIMAL(5,2) NOT NULL DEFAULT 100,start_date DATE NULL,end_date DATE NULL,status ENUM('assigned','active','released') NOT NULL DEFAULT 'assigned',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_project_staff(project_id,staff_id),CONSTRAINT fk_resource_project FOREIGN KEY(project_id) REFERENCES client_projects(id) ON DELETE CASCADE,CONSTRAINT fk_resource_staff FOREIGN KEY(staff_id) REFERENCES staff_members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS project_tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,assigned_staff_id BIGINT UNSIGNED NULL,parent_task_id BIGINT UNSIGNED NULL,title VARCHAR(180) NOT NULL,description TEXT NULL,priority ENUM('low','medium','high','urgent') NOT NULL DEFAULT 'medium',status ENUM('todo','in_progress','blocked','completed','cancelled') NOT NULL DEFAULT 'todo',start_date DATE NULL,due_date DATE NULL,estimated_hours DECIMAL(8,2) NOT NULL DEFAULT 0,completed_at DATETIME NULL,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_task_project(project_id),INDEX idx_task_staff(assigned_staff_id),CONSTRAINT fk_task_project FOREIGN KEY(project_id) REFERENCES client_projects(id) ON DELETE CASCADE,CONSTRAINT fk_task_staff FOREIGN KEY(assigned_staff_id) REFERENCES staff_members(id) ON DELETE SET NULL,CONSTRAINT fk_task_parent FOREIGN KEY(parent_task_id) REFERENCES project_tasks(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS time_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,task_id BIGINT UNSIGNED NULL,project_id BIGINT UNSIGNED NOT NULL,staff_id BIGINT UNSIGNED NOT NULL,work_date DATE NOT NULL,hours DECIMAL(8,2) NOT NULL,billable TINYINT(1) NOT NULL DEFAULT 1,hourly_rate DECIMAL(15,2) NOT NULL DEFAULT 0,description VARCHAR(500) NULL,status ENUM('draft','submitted','approved','rejected') NOT NULL DEFAULT 'draft',approved_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_time_project(project_id),INDEX idx_time_staff(staff_id),INDEX idx_time_date(work_date),CONSTRAINT fk_time_task FOREIGN KEY(task_id) REFERENCES project_tasks(id) ON DELETE SET NULL,CONSTRAINT fk_time_project FOREIGN KEY(project_id) REFERENCES client_projects(id) ON DELETE CASCADE,CONSTRAINT fk_time_staff FOREIGN KEY(staff_id) REFERENCES staff_members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;